75e666d2-72ab-4192-9883-23f954fc578d	DW -> MV Refresh -> All	1782224335187	1782224335187	multiple	multiple	0 40 8 * * 1-6	\N	\N	\N	t	t	2026-06-26 23:34:23.195421	2026-07-15 08:40:01.378898	\N	\N	\N	\N	\N	47e77de2-09d0-49f7-b7e2-503da13687e2	866bb165-0112-475e-bfe1-807c2590d875	[{"id":"template-tpl_1782491425486","sourceTable":"query","targetTable":"query","customQuerySource":"SELECT *\\n  FROM sch_setting.execute_query(\\n       (SELECT string_agg(\\n               format(\\n                 '(SELECT %L AS nama_mv, CURRENT_DATE AS tgl_refresh)',\\n                 CONCAT(schemaname, '.', matviewname)\\n               ),\\n               E'\\\\nUNION ALL\\\\n'\\n               ) || E'\\\\nORDER BY 1'\\n          FROM pg_matviews)::text)\\n       t(nama_mv text, tgl_refresh date)","customQueryTarget":"SELECT *\\n  FROM sch_setting.execute_query(\\n       (SELECT string_agg(\\n               format(\\n                  '(SELECT %L AS nama_mv, tgl_refresh::date FROM %I.%I LIMIT 1)',\\n                  CONCAT(schemaname, '.', matviewname),\\n                  schemaname,\\n                  matviewname\\n               ),\\n               E'\\\\nUNION ALL\\\\n'\\n               ) || E'\\\\nORDER BY 1'\\n          FROM pg_matviews)::text)\\n       t(nama_mv text, tgl_refresh date)","primaryKeys":["nama_mv"],"isManualQuerySource":true,"isManualQueryTarget":true}]	f	f
60ff21dd-8512-46bb-bcf5-792dc35b06a3	MBI -> DW -> sch_trans.trm_kartu_stock_baik_hpp_rekap (2026)	1781690258984	1782224335187	multiple	multiple	0 8 8 * * 1-6	\N	\N	\N	t	t	2026-06-30 10:16:10.20518	2026-07-15 08:08:16.882845	\N	\N	\N	\N	\N	47e77de2-09d0-49f7-b7e2-503da13687e2	866bb165-0112-475e-bfe1-807c2590d875	[{"id":"template-tpl_1782788686496","sourceTable":"query","targetTable":"query","customQuerySource":"WITH q_stock AS (\\nSELECT a.tahun, a.bulan, a.kode_cabang, a.kode_barang,\\n       'SALDO-AWAL' AS kode_tran, 'SD' AS status_tran,  \\n       a.qty_saldo AS qty, ROUND(a.qty_saldo * a.hrg_pokok, 4) AS total\\n  FROM sch_erp_inventory.trm_harga_pokok_saldo a\\n WHERE (a.tahun BETWEEN '2026' AND '2026') AND a.qty_saldo <> 0\\nUNION ALL \\nSELECT TO_CHAR(a.tgl_acc, 'YYYY') AS tahun, TO_CHAR(a.tgl_acc, 'MM') AS bulan, a.kode_cabang,  a.kode_barang,\\n       a.kode_tran, a.status_tran,\\n       a.qty_tran AS qty, ROUND(a.qty_tran * a.hrg_pokok, 4) AS total\\n  FROM sch_erp_inventory.trm_harga_pokok_tran a\\n WHERE (TO_CHAR(a.tgl_acc, 'YYYY') BETWEEN '2026' AND '2026')\\n)\\nSELECT x.tahun, x.bulan, x.kode_cabang, \\n       SUM(CASE WHEN x.kode_tran = 'SALDO-AWAL' THEN x.qty ELSE 0 END) AS qty_sd_awal,\\n       SUM(CASE WHEN x.kode_tran = 'SALDO-AWAL' THEN x.total ELSE 0 END) AS tot_sd_awal,\\n       SUM(CASE WHEN x.kode_tran = 'PENERIMAAN-SPG' THEN x.qty ELSE 0 END) AS qty_spg,\\n       SUM(CASE WHEN x.kode_tran = 'PENERIMAAN-SPG' THEN x.total ELSE 0 END) AS tot_spg,\\n       SUM(CASE WHEN x.kode_tran = 'PENJUALAN-BATAL' THEN x.qty ELSE 0 END) AS qty_penjualan_batal,\\n       SUM(CASE WHEN x.kode_tran = 'PENJUALAN-BATAL' THEN x.total ELSE 0 END) AS tot_penjualan_batal,\\n       SUM(CASE WHEN x.kode_tran = 'RETUR-JUAL' THEN x.qty ELSE 0 END) AS qty_retur_jual,\\n       SUM(CASE WHEN x.kode_tran = 'RETUR-JUAL' THEN x.total ELSE 0 END) AS tot_retur_jual,\\n       SUM(CASE WHEN x.kode_tran = 'PENERIMAAN-LAIN' THEN x.qty ELSE 0 END) AS qty_penerimaan_lain,\\n       SUM(CASE WHEN x.kode_tran = 'PENERIMAAN-LAIN' THEN x.total ELSE 0 END) AS tot_penerimaan_lain,\\n       SUM(CASE WHEN x.kode_tran = 'PENERIMAAN-RUSAK' THEN x.qty ELSE 0 END) AS qty_penerimaan_rusak,\\n       SUM(CASE WHEN x.kode_tran = 'PENERIMAAN-RUSAK' THEN x.total ELSE 0 END) AS tot_penerimaan_rusak,\\n       SUM(CASE WHEN x.kode_tran = 'PINDAH-GUDANG-MASUK' THEN x.qty ELSE 0 END) AS qty_pindah_gudang_masuk,\\n       SUM(CASE WHEN x.kode_tran = 'PINDAH-GUDANG-MASUK' THEN x.total ELSE 0 END) AS tot_pindah_gudang_masuk,\\n       SUM(CASE WHEN x.kode_tran = 'LPP-REQUEST' THEN x.qty ELSE 0 END) AS qty_lpp_request,\\n       SUM(CASE WHEN x.kode_tran = 'LPP-REQUEST' THEN x.total ELSE 0 END) AS tot_lpp_request,\\n       SUM(CASE WHEN x.kode_tran = 'LPP-CANCELLATION-MATERIAL' THEN x.qty ELSE 0 END) AS qty_lpp_cancellation_material,\\n       SUM(CASE WHEN x.kode_tran = 'LPP-CANCELLATION-MATERIAL' THEN x.total ELSE 0 END) AS tot_lpp_cancellation_material,\\n       SUM(CASE WHEN x.kode_tran = 'UNPACKING-MATERIAL' THEN x.qty ELSE 0 END) AS qty_unpacking_material,\\n       SUM(CASE WHEN x.kode_tran = 'UNPACKING-MATERIAL' THEN x.total ELSE 0 END) AS tot_unpacking_material,\\n       SUM(CASE WHEN x.kode_tran = 'PENJUALAN' THEN x.qty ELSE 0 END) AS qty_penjualan,\\n       SUM(CASE WHEN x.kode_tran = 'PENJUALAN' THEN x.total ELSE 0 END) AS tot_penjualan,\\n       SUM(CASE WHEN x.kode_tran = 'TUKAR-BARANG' THEN x.qty ELSE 0 END) AS qty_tukar_barang,\\n       SUM(CASE WHEN x.kode_tran = 'TUKAR-BARANG' THEN x.total ELSE 0 END) AS tot_tukar_barang,\\n       SUM(CASE WHEN x.kode_tran = 'KLAIM-BARANG' THEN x.qty ELSE 0 END) AS qty_klaim_barang,\\n       SUM(CASE WHEN x.kode_tran = 'KLAIM-BARANG' THEN x.total ELSE 0 END) AS tot_klaim_barang,\\n       SUM(CASE WHEN x.kode_tran = 'PENGELUARAN-LAIN' THEN x.qty ELSE 0 END) AS qty_pengeluaran_lain,\\n       SUM(CASE WHEN x.kode_tran = 'PENGELUARAN-LAIN' THEN x.total ELSE 0 END) AS tot_pengeluaran_lain,\\n       SUM(CASE WHEN x.kode_tran = 'PENGELUARAN-TTB' THEN x.qty ELSE 0 END) AS qty_pengeluaran_ttb,\\n       SUM(CASE WHEN x.kode_tran = 'PENGELUARAN-TTB' THEN x.total ELSE 0 END) AS tot_pengeluaran_ttb,\\n       SUM(CASE WHEN x.kode_tran = 'PINDAH-GUDANG-KELUAR' THEN x.qty ELSE 0 END) AS qty_pindah_gudang_keluar,\\n       SUM(CASE WHEN x.kode_tran = 'PINDAH-GUDANG-KELUAR' THEN x.total ELSE 0 END) AS tot_pindah_gudang_keluar,\\n       SUM(CASE WHEN x.kode_tran = 'LPP-REQUEST-MATERIAL' THEN x.qty ELSE 0 END) AS qty_lpp_request_material,\\n       SUM(CASE WHEN x.kode_tran = 'LPP-REQUEST-MATERIAL' THEN x.total ELSE 0 END) AS tot_lpp_request_material,\\n       SUM(CASE WHEN x.kode_tran = 'LPP-CANCELLATION' THEN x.qty ELSE 0 END) AS qty_lpp_cancellation,\\n       SUM(CASE WHEN x.kode_tran = 'LPP-CANCELLATION' THEN x.total ELSE 0 END) AS tot_lpp_cancellation,\\n       SUM(CASE WHEN x.kode_tran = 'UNPACKING' THEN x.qty ELSE 0 END) AS qty_unpacking,\\n       SUM(CASE WHEN x.kode_tran = 'UNPACKING' THEN x.total ELSE 0 END) AS tot_unpacking\\n  FROM q_stock x\\n GROUP BY x.tahun, x.bulan, x.kode_cabang\\n ORDER BY x.tahun, x.bulan, x.kode_cabang ","customQueryTarget":"SELECT a.tahun, a.bulan, a.kode_cabang, \\n       SUM(a.qty_sd_awal) AS qty_sd_awal, SUM(a.tot_sd_awal) AS tot_sd_awal,\\n       SUM(a.qty_spg) AS qty_spg, SUM(a.tot_spg) AS tot_spg,\\n       SUM(a.qty_penjualan_batal) AS qty_penjualan_batal, SUM(a.tot_penjualan_batal) AS tot_penjualan_batal,\\n       SUM(a.qty_retur_jual) AS qty_retur_jual, SUM(a.tot_retur_jual) AS tot_retur_jual,\\n       SUM(a.qty_penerimaan_lain) AS qty_penerimaan_lain, SUM(a.tot_penerimaan_lain) AS tot_penerimaan_lain,\\n       SUM(a.qty_penerimaan_rusak) AS qty_penerimaan_rusak, SUM(a.tot_penerimaan_rusak) AS tot_penerimaan_rusak,\\n       SUM(a.qty_pindah_gudang_masuk) AS qty_pindah_gudang_masuk, SUM(a.tot_pindah_gudang_masuk) AS tot_pindah_gudang_masuk,\\n       SUM(a.qty_lpp_request) AS qty_lpp_request, SUM(a.tot_lpp_request) AS tot_lpp_request,\\n       SUM(a.qty_lpp_cancellation_material) AS qty_lpp_cancellation_material, SUM(a.tot_lpp_cancellation_material) AS tot_lpp_cancellation_material,\\n       SUM(a.qty_unpacking_material) AS qty_unpacking_material, SUM(a.tot_unpacking_material) AS tot_unpacking_material,\\n       SUM(a.qty_penjualan) AS qty_penjualan, SUM(a.tot_penjualan) AS tot_penjualan,\\n       SUM(a.qty_tukar_barang) AS qty_tukar_barang, SUM(a.tot_tukar_barang) AS tot_tukar_barang,\\n       SUM(a.qty_klaim_barang) AS qty_klaim_barang, SUM(a.tot_klaim_barang) AS tot_klaim_barang,\\n       SUM(a.qty_pengeluaran_lain) AS qty_pengeluaran_lain, SUM(a.tot_pengeluaran_lain) AS tot_pengeluaran_lain,\\n       SUM(a.qty_pengeluaran_ttb) AS qty_pengeluaran_ttb, SUM(a.tot_pengeluaran_ttb) AS tot_pengeluaran_ttb,\\n       SUM(a.qty_pindah_gudang_keluar) AS qty_pindah_gudang_keluar, SUM(a.tot_pindah_gudang_keluar) AS tot_pindah_gudang_keluar,\\n       SUM(a.qty_lpp_request_material) AS qty_lpp_request_material, SUM(a.tot_lpp_request_material) AS tot_lpp_request_material,\\n       SUM(a.qty_lpp_cancellation) AS qty_lpp_cancellation, SUM(a.tot_lpp_cancellation) AS tot_lpp_cancellation,\\n       SUM(a.qty_unpacking) AS qty_unpacking, SUM(a.tot_unpacking) AS tot_unpacking\\n  FROM sch_trans.trm_kartu_stock_baik_hpp_rekap a\\n WHERE a.kode_perusahaan = 'P201' AND (a.tahun BETWEEN '2026' AND '2026')\\n GROUP BY a.tahun, a.bulan, a.kode_cabang\\n ORDER BY a.tahun, a.bulan, a.kode_cabang","primaryKeys":["tahun","bulan","kode_cabang"],"isManualQuerySource":true,"isManualQueryTarget":true}]	f	f
