tpl_1783348961445	MKN -> Cek PO Merek Kosong	query	1783347507839	1783347507839	\N	SELECT 'PO-SUPPLIER' AS jenis_po, a.no_tran, a.tgl_tran, \n       CASE WHEN COALESCE(a.kode_merek, '') = '' THEN 'TIDAK-ADA-MEREK' ELSE 'ADA-MEREK' END AS kode_merek\n  FROM sch_erp_inventory.trh_order_pembelian a\n WHERE a.kode_klasifikasi = '01' AND a.approval_status = 'IP'\nUNION ALL  \nSELECT 'PO-CABANG' AS jenis_po, a.no_tran, a.tgl_tran, \n       CASE WHEN COALESCE(a.list_kode_merek, '') = '' THEN 'TIDAK-ADA-MEREK' ELSE 'ADA-MEREK' END AS kode_merek\n  FROM sch_erp_inventory.trh_po_cabang a\n WHERE a.kode_klasifikasi = '01' AND a.approval_status = 'IP'	SELECT 'PO-SUPPLIER' AS jenis_po, a.no_tran, a.tgl_tran, \n       'ADA-MEREK' AS kode_merek\n  FROM sch_erp_inventory.trh_order_pembelian a\n WHERE a.kode_klasifikasi = '01' AND a.approval_status = 'IP'\nUNION ALL  \nSELECT 'PO-CABANG' AS jenis_po, a.no_tran, a.tgl_tran, \n       'ADA-MEREK' AS kode_merek\n  FROM sch_erp_inventory.trh_po_cabang a\n WHERE a.kode_klasifikasi = '01' AND a.approval_status = 'IP'	2026-07-06 21:42:42.112977	jenis_po, no_tran
tpl_1783665606164	MBI -> DW -> Selisih Unit Entry, Jasa, Produk, HPP	query	1781690258984	1782224825829	\N	SELECT TO_CHAR(b.transdate, 'YYYY') AS periode_tahun, TO_CHAR(b.transdate, 'MM') AS periode_bulan,\n       COUNT(DISTINCT CASE WHEN a.typecode = 'S' THEN b.transno ELSE null END) AS unit_entry,\n       SUM(CASE WHEN a.typecode = 'S' THEN a.dpp ELSE 0 END) AS dpp_jasa,\n       SUM(CASE WHEN a.typecode = 'P' THEN a.dpp ELSE 0 END) AS dpp_produk \n  FROM sch_pos.tbl_pos_detail a\n       JOIN sch_pos.tbl_pos b ON a.transno = b.transno AND a.storeid = b.storeid\n WHERE b.status = 'A' AND TO_CHAR(b.transdate, 'YYYY') >= '2022'\n GROUP BY 1, 2 \n ORDER BY 1, 2\n	SELECT a.periode_tahun, a.periode_bulan, \n       COUNT(DISTINCT CASE WHEN a.nama_bentuk_barang = 'JASA' THEN a.no_fak_jl ELSE null END) AS unit_entry,\n       SUM(CASE WHEN a.nama_bentuk_barang = 'JASA' THEN a.total_dpp ELSE 0 END) AS dpp_jasa,\n       SUM(CASE WHEN a.nama_bentuk_barang = 'BARANG' THEN a.total_dpp ELSE 0 END) AS dpp_produk\n  FROM sch_mbi.view_data_penjualan_rinci_mbi a\n GROUP BY a.periode_tahun, a.periode_bulan \n ORDER BY a.periode_tahun, a.periode_bulan	2026-07-10 13:40:06.642231	periode_tahun, periode_bulan
tpl_1783925535540	MBI -> DW -> Selisih Unit Entry, Jasa, Produk, HPP - Detail	query	1781690258984	1782224825829	\N	WITH q_data AS (\n   SELECT TO_CHAR(b.transdate, 'YYYY') AS periode_tahun, TO_CHAR(b.transdate, 'MM') AS periode_bulan,\n          b.transno AS no_fak_jl, \n          CASE WHEN a.typecode = 'S' THEN d.servicecode ELSE c.productcode END AS kode_barang,\n          CASE WHEN a.typecode = 'S' THEN d.servicename ELSE c.productname END AS nama_barang,\n          CASE WHEN a.typecode = 'S' THEN 'JASA' ELSE 'BARANG' END AS nama_bentuk_barang,\n          CASE WHEN a.typecode = 'S' THEN 0 ELSE 1 END AS unit_entry,\n          CASE WHEN a.typecode = 'S' THEN a.dpp ELSE 0 END AS dpp_jasa,\n          CASE WHEN a.typecode = 'P' THEN a.dpp ELSE 0 END AS dpp_produk \n     FROM sch_pos.tbl_pos_detail a\n          JOIN sch_pos.tbl_pos b ON a.transno = b.transno AND a.storeid = b.storeid\n          LEFT JOIN sch_pos.tbl_stock c ON a.typecode = 'P' AND a.productid = c.id  \n          LEFT JOIN sch_pos.tbl_service d ON a.typecode = 'S' AND a.productid = d.id \n    WHERE b.status = 'A' AND TO_CHAR(b.transdate, 'YYYYMM') = '202306'\n)\nSELECT x.periode_tahun, x.periode_bulan,\n       x.no_fak_jl, x.kode_barang, x.nama_barang, x.nama_bentuk_barang,\n       x.unit_entry, x.dpp_jasa, x.dpp_produk\n  FROM q_data x\n ORDER BY x.periode_tahun, x.periode_bulan, x.no_fak_jl, x.kode_barang	SELECT a.periode_tahun, a.periode_bulan, \n       a.no_fak_jl, a.kode_barang, a.nama_barang, a.nama_bentuk_barang,\n       CASE WHEN a.nama_bentuk_barang = 'JASA' THEN 0 ELSE 1 END AS unit_entry,\n       CASE WHEN a.nama_bentuk_barang = 'JASA' THEN a.total_dpp ELSE 0 END AS dpp_jasa,\n       CASE WHEN a.nama_bentuk_barang = 'BARANG' THEN a.total_dpp ELSE 0 END AS dpp_produk\n  FROM sch_mbi.view_data_penjualan_rinci_mbi a\n WHERE a.periode_tahun || a.periode_bulan = '202306'\n ORDER BY a.periode_tahun, a.periode_bulan, a.no_fak_jl, a.kode_barang	2026-07-13 13:52:15.965823	periode_tahun, periode_bulan, no_fak_jl, kode_barang
